dth:300px){.chAffinityBody{grid-template-columns:84px minmax(0,1fr);gap:16px}.chHeartMeter,.chHeartMeter svg{width:84px;height:84px}.chAffinityMetrics{gap:10px}.chMemoryStats .chAffinityScore strong{font-size:28px}}@media(prefers-reduced-motion:reduce){.chHeartWave{animation:none;will-change:auto}}

